package bo.soboce.comedor;

import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.zip.*;

/** Small streaming OOXML writer. User text is always inline text, never a formula. */
final class ExcelReport {
    static final String MIME="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
    static final String NS="http://schemas.openxmlformats.org/spreadsheetml/2006/main";
    static String filename(JSONObject report){return "consumos-"+(report.optString("period").equals("day")?report.optString("date"):report.optString("month"))+".xlsx";}
    static String xml(String value){StringBuilder s=new StringBuilder();value.codePoints().filter(c->c==9||c==10||c==13||c>=32&&c<=0xD7FF||c>=0xE000&&c<=0xFFFD||c>=0x10000&&c<=0x10FFFF).forEach(s::appendCodePoint);return s.toString().replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
    static String text(String ref,String v,int style){return "<c r=\""+ref+"\" s=\""+style+"\" t=\"inlineStr\"><is><t xml:space=\"preserve\">"+xml(v)+"</t></is></c>";}
    static String number(String ref,double v,int style){if(!Double.isFinite(v))throw new IllegalArgumentException("Importe inválido");return "<c r=\""+ref+"\" s=\""+style+"\"><v>"+v+"</v></c>";}
    static void entry(ZipOutputStream zip,String path,String data)throws IOException{zip.putNextEntry(new ZipEntry(path));zip.write(data.getBytes(StandardCharsets.UTF_8));zip.closeEntry();}
    static void write(OutputStream output,JSONObject report,String company,String plant)throws Exception {
        JSONArray rows=report.getJSONArray("exportItems");PeerConfig.require(rows.length()<=100000,"Exporta un período más pequeño (máximo 100.000 registros).");
        try(ZipOutputStream zip=new ZipOutputStream(output)){
            entry(zip,"[Content_Types].xml","<?xml version=\"1.0\" encoding=\"UTF-8\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/><Override PartName=\"/xl/styles.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml\"/><Override PartName=\"/xl/worksheets/sheet1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/><Override PartName=\"/xl/worksheets/sheet2.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/></Types>");
            entry(zip,"_rels/.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>");
            entry(zip,"xl/workbook.xml","<workbook xmlns=\""+NS+"\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets><sheet name=\"Resumen\" sheetId=\"1\" r:id=\"rId1\"/><sheet name=\"Entregas\" sheetId=\"2\" r:id=\"rId2\"/></sheets></workbook>");
            entry(zip,"xl/_rels/workbook.xml.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet1.xml\"/><Relationship Id=\"rId2\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet2.xml\"/><Relationship Id=\"rId3\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles\" Target=\"styles.xml\"/></Relationships>");
            entry(zip,"xl/styles.xml","<styleSheet xmlns=\""+NS+"\"><numFmts count=\"3\"><numFmt numFmtId=\"164\" formatCode=\"dd/mm/yyyy\"/><numFmt numFmtId=\"165\" formatCode=\"hh:mm:ss\"/><numFmt numFmtId=\"166\" formatCode=\"&quot;Bs &quot;#,##0.00\"/></numFmts><fonts count=\"3\"><font><sz val=\"11\"/><name val=\"Calibri\"/><color rgb=\"FF102039\"/></font><font><b/><sz val=\"11\"/><name val=\"Calibri\"/><color rgb=\"FFFFFFFF\"/></font><font><b/><sz val=\"20\"/><name val=\"Calibri\"/><color rgb=\"FF102039\"/></font></fonts><fills count=\"3\"><fill><patternFill patternType=\"none\"/></fill><fill><patternFill patternType=\"gray125\"/></fill><fill><patternFill patternType=\"solid\"><fgColor rgb=\"FF102039\"/><bgColor indexed=\"64\"/></patternFill></fill></fills><borders count=\"1\"><border><left/><right/><top/><bottom/><diagonal/></border></borders><cellStyleXfs count=\"1\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\"/></cellStyleXfs><cellXfs count=\"7\"><xf numFmtId=\"0\" fontId=\"0\" fillId=\"0\" borderId=\"0\" xfId=\"0\"/><xf numFmtId=\"0\" fontId=\"1\" fillId=\"2\" borderId=\"0\" xfId=\"0\"/><xf numFmtId=\"164\" fontId=\"0\" fillId=\"0\" borderId=\"0\" xfId=\"0\" applyNumberFormat=\"1\"/><xf numFmtId=\"165\" fontId=\"0\" fillId=\"0\" borderId=\"0\" xfId=\"0\" applyNumberFormat=\"1\"/><xf numFmtId=\"166\" fontId=\"0\" fillId=\"0\" borderId=\"0\" xfId=\"0\" applyNumberFormat=\"1\"/><xf numFmtId=\"0\" fontId=\"2\" fillId=\"0\" borderId=\"0\" xfId=\"0\"/><xf numFmtId=\"1\" fontId=\"0\" fillId=\"0\" borderId=\"0\" xfId=\"0\" applyNumberFormat=\"1\"/></cellXfs><cellStyles count=\"1\"><cellStyle name=\"Normal\" xfId=\"0\" builtinId=\"0\"/></cellStyles></styleSheet>");
            StringBuilder summary=new StringBuilder("<worksheet xmlns=\""+NS+"\"><sheetViews><sheetView workbookViewId=\"0\" showGridLines=\"0\"/></sheetViews><cols><col min=\"1\" max=\"1\" width=\"34\" customWidth=\"1\"/><col min=\"2\" max=\"2\" width=\"58\" customWidth=\"1\"/></cols><sheetData>");
            summary.append("<row r=\"1\" ht=\"32\" customHeight=\"1\">").append(text("A1","Consumos del comedor",5)).append("</row>");
            String[] labels={"Empresa","Planta","Período","Raciones entregadas","Trabajadores distintos","Importe con tarifa registrada","Raciones sin tarifa","Registros por revisar","Desayunos","Almuerzos","Cenas","Dietas"};
            Object[] values={company,plant,report.optString("period").equals("day")?report.optString("date"):report.optString("month"),report.getInt("count"),report.getInt("workers"),report.getDouble("total"),report.getInt("unpriced"),report.getInt("conflicts"),report.getJSONObject("byMeal").optInt("desayuno"),report.getJSONObject("byMeal").optInt("almuerzo"),report.getJSONObject("byMeal").optInt("cena"),report.getJSONObject("byMeal").optInt("dieta")};
            for(int i=0;i<labels.length;i++){int n=i+3;summary.append("<row r=\"").append(n).append("\" ht=\"24\" customHeight=\"1\">").append(text("A"+n,labels[i],1)).append(values[i] instanceof Number?number("B"+n,((Number)values[i]).doubleValue(),i==5?4:6):text("B"+n,values[i].toString(),0)).append("</row>");}
            summary.append("<row r=\"16\">").append(text("A16","Los posibles duplicados se incluyen y se señalan en Entregas.",0)).append("</row><row r=\"17\">").append(text("A17","Copia de los consumos recibidos; pueden faltar teléfonos sin sincronizar.",0)).append("</row></sheetData></worksheet>");entry(zip,"xl/worksheets/sheet1.xml",summary.toString());
            zip.putNextEntry(new ZipEntry("xl/worksheets/sheet2.xml"));Writer w=new OutputStreamWriter(zip,StandardCharsets.UTF_8);
            w.write("<worksheet xmlns=\""+NS+"\"><sheetViews><sheetView workbookViewId=\"0\"><pane ySplit=\"1\" topLeftCell=\"A2\" activePane=\"bottomLeft\" state=\"frozen\"/></sheetView></sheetViews><cols>");
            int[] widths={14,12,24,40,16,28,30,18,22,30,38,24,20};for(int i=0;i<widths.length;i++)w.write("<col min=\""+(i+1)+"\" max=\""+(i+1)+"\" width=\""+widths[i]+"\" customWidth=\"1\"/>");w.write("</cols><sheetData><row r=\"1\" ht=\"26\" customHeight=\"1\">");
            String[] headings={"Fecha","Hora","Identificador","Trabajador","Comida","Planta","Encargado","Importe (Bs)","Centro de costo","Registro","Origen","Revisión","Tarifa pendiente"};
            for(int i=0;i<headings.length;i++)w.write(text(""+(char)('A'+i)+1,headings[i],1));w.write("</row>");
            for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);int n=i+2;w.write("<row r=\""+n+"\">");w.write(number("A"+n,ChronoUnit.DAYS.between(LocalDate.of(1899,12,30),LocalDate.parse(r.getString("fecha"))),2));w.write(number("B"+n,LocalTime.parse(r.getString("hora")).toSecondOfDay()/86400d,3));String[] keys={"persona","nombre","comida","planta","operador","precio","centroCosto","registro","origen","revision","precioPendiente"};for(int k=0;k<keys.length;k++){String ref=""+(char)('C'+k)+n;if(k==5){if(!r.optBoolean("precioPendiente"))w.write(number(ref,r.getDouble("precio"),4));}else w.write(text(ref,k==10?(r.optBoolean("precioPendiente")?"Sí":"No"):r.optString(keys[k]),0));}w.write("</row>");}
            w.write("</sheetData><autoFilter ref=\"A1:M"+(rows.length()+1)+"\"/><pageSetup orientation=\"landscape\" paperSize=\"1\"/></worksheet>");w.flush();zip.closeEntry();
        }
    }
}
